                         for dr in range(n) for dc in range(n))
            if masked and template[tr][tc] == 2:
                for dr in range(n):
                    for dc in range(n):
                        out[r0 + dr][c0 + dc] = template[dr][dc]

    # Highlight the indexed cell in each motif/tile.
    for tr in range(n):
        for tc in range(n):
            r, c = tr * stride + tr, tc * stride + tc
            if out[r][c] == 2:
                out[r][c] = 8
    return out

